package es.criosrango.shared
import es.criosrango.shared.model.ProductPrices
import es.criosrango.shared.model.StoreCategory
import es.criosrango.shared.model.StoreProduct
import kotlinx.coroutines.CompletableDeferred
import kotlinx.coroutines.test.advanceUntilIdle
import kotlinx.coroutines.test.runCurrent
import kotlinx.coroutines.test.runTest
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFalse

class IosNovedadesTest {
 private class Fake:StoreNovedadesDataSource {
  val tree=listOf(StoreCategory(id=10,name="Bautizo",slug="bautizo"),StoreCategory(id=11,parent=10,name="Bautizo ropa"),StoreCategory(id=20,name="Bebé niña",slug="bebe-nina"),StoreCategory(id=21,parent=20,name="Vestidos"),StoreCategory(id=30,name="Bebé niño",slug="bebe-nino"),StoreCategory(id=40,name="Niña",slug="nina"),StoreCategory(id=41,parent=40,name="Vestidos"),StoreCategory(id=50,name="Niño",slug="nino"),StoreCategory(id=60,name="Comunión niña",slug="comunion-nina"),StoreCategory(id=61,parent=60,name="Vestidos"),StoreCategory(id=70,name="Comunión niño",slug="comunion-nino"),StoreCategory(id=80,name="Mujer",slug="mujer"),StoreCategory(id=81,parent=80,name="Vestidos"),StoreCategory(id=90,name="Hombre",slug="hombre"),StoreCategory(id=100,name="Recién nacido",slug="recien-nacido"),StoreCategory(id=101,parent=100,name="Pijamas"))
  var calls=0;var gate:CompletableDeferred<CatalogPage<StoreProduct>>?=null
  val pages=mutableListOf<Int>();val sizes=mutableListOf<Int>();val cats=mutableListOf<List<Int>>();val sorts=mutableListOf<StoreNovedadesSort>()
  var products=listOf(StoreProduct(id=1,name="Bautizo",prices=ProductPrices(price="100"),categories=listOf(StoreCategory(id=11))),StoreProduct(id=2,name="Bebé niña",prices=ProductPrices(price="200"),categories=listOf(StoreCategory(id=21))),StoreProduct(id=3,name="Bebé niño",prices=ProductPrices(price="50"),categories=listOf(StoreCategory(id=30))),StoreProduct(id=4,name="Niña",prices=ProductPrices(price="90"),categories=listOf(StoreCategory(id=41))),StoreProduct(id=5,name="Niño",prices=ProductPrices(price="80"),categories=listOf(StoreCategory(id=50))),StoreProduct(id=6,name="Comunión niña",prices=ProductPrices(price="70"),categories=listOf(StoreCategory(id=61))),StoreProduct(id=7,name="Comunión niño",prices=ProductPrices(price="60"),categories=listOf(StoreCategory(id=70))),StoreProduct(id=8,name="Mujer",prices=ProductPrices(price="40"),categories=listOf(StoreCategory(id=81))),StoreProduct(id=9,name="Hombre",prices=ProductPrices(price="30"),categories=listOf(StoreCategory(id=90))),StoreProduct(id=10,name="Recién nacido",prices=ProductPrices(price="20"),categories=listOf(StoreCategory(id=101))))
  override suspend fun categories(page:Int,perPage:Int)=if(page==1)tree else emptyList()
  override suspend fun products(page:Int,perPage:Int,categoryIds:List<Int>,sort:StoreNovedadesSort):CatalogPage<StoreProduct>{calls++;pages+=page;sizes+=perPage;cats+=categoryIds;sorts+=sort;if(calls==1)gate?.let{return it.await()};return CatalogPage(products,true,999)}
 }
 @Test fun initialQueryIsOneGlobalRecentPageOf24()=runTest{val f=Fake();val c=StoreNovedadesController(this,f);c.start();advanceUntilIdle();assertEquals(1,f.calls);assertEquals(listOf(1),f.pages);assertEquals(listOf(24),f.sizes);assertEquals(listOf(emptyList()),f.cats);assertEquals(listOf(StoreNovedadesSort.RECENT),f.sorts);assertEquals(10,c.state.value.paging.items.size);assertFalse(c.state.value.paging.hasMore)}
 @Test fun categoryGroupsFilterOnlyLoadedSnapshot()=runTest{val f=Fake();val c=StoreNovedadesController(this,f);c.start();advanceUntilIdle();c.selectAudience(StoreNovedadesAudience.CRIOS);assertEquals(listOf(2,3,4,5),c.state.value.paging.items.map{it.id}.sorted());c.selectAudience(StoreNovedadesAudience.COMUNION);assertEquals(listOf(6,7),c.state.value.paging.items.map{it.id}.sorted());c.selectAudience(StoreNovedadesAudience.BAUTIZO);assertEquals(listOf(1),c.state.value.paging.items.map{it.id});c.selectAudience(StoreNovedadesAudience.MUJER);assertEquals(listOf(8),c.state.value.paging.items.map{it.id});c.selectAudience(StoreNovedadesAudience.HOMBRE);assertEquals(listOf(9),c.state.value.paging.items.map{it.id});c.selectAudience(StoreNovedadesAudience.RECIEN_NACIDO);assertEquals(listOf(10),c.state.value.paging.items.map{it.id});c.selectAudience(StoreNovedadesAudience.ALL);assertEquals((1..10).toList(),c.state.value.paging.items.map{it.id});assertEquals(1,f.calls)}
 @Test fun descendantResolutionUsesExistingTaxonomy() {assertEquals(listOf(20,21),resolveAudienceCategoryIds(listOf(StoreCategory(id=20,name="Bebé niña",slug="bebe-nina"),StoreCategory(id=21,parent=20,name="Vestidos")),StoreNovedadesAudience.CRIOS))}
 @Test fun sortChangesOrderNotDatasetOrApiRequest()=runTest{val f=Fake();val c=StoreNovedadesController(this,f);c.start();advanceUntilIdle();val ids=c.state.value.paging.items.map{it.id}.toSet();c.selectSort(StoreNovedadesSort.PRICE_ASC);assertEquals(listOf(10,9,8,3,7,6,5,4,1,2),c.state.value.paging.items.map{it.id});c.selectSort(StoreNovedadesSort.PRICE_DESC);assertEquals(ids,c.state.value.paging.items.map{it.id}.toSet());assertEquals(1,f.calls);assertEquals(listOf(StoreNovedadesSort.RECENT),f.sorts);assertEquals(c.state.value.paging.items.size,c.state.value.paging.totalItems)}
 @Test fun paginationDisabledAndRetryReloadsOnlyGlobalPage()=runTest{val f=Fake();val c=StoreNovedadesController(this,f);c.start();advanceUntilIdle();c.loadNextPage();assertEquals(1,f.calls);assertFalse(c.state.value.paging.hasMore);c.selectAudience(StoreNovedadesAudience.CRIOS);c.retry();advanceUntilIdle();assertEquals(2,f.calls);assertEquals(listOf(1,1),f.pages);assertEquals(listOf(24,24),f.sizes);assertEquals(listOf(emptyList(),emptyList()),f.cats);assertEquals(StoreNovedadesAudience.CRIOS,c.state.value.selectedAudience)}
 @Test fun staleResponseCannotOverwriteLatestRefresh()=runTest{val f=Fake();val gate=CompletableDeferred<CatalogPage<StoreProduct>>();f.gate=gate;val c=StoreNovedadesController(this,f);c.start();runCurrent();c.refresh();runCurrent();assertEquals(2,f.calls);gate.complete(CatalogPage(listOf(StoreProduct(id=999)),false,1));advanceUntilIdle();assertFalse(c.state.value.paging.items.any{it.id==999});assertEquals((1..10).toList(),c.state.value.paging.items.map{it.id})}
 @Test fun responseIsCappedAt24AndRecentOrderIsPreserved()=runTest{val f=Fake();f.products=(1..30).map{StoreProduct(id=it)};val c=StoreNovedadesController(this,f);c.start();advanceUntilIdle();assertEquals(24,c.state.value.paging.items.size);assertFalse(c.state.value.paging.hasMore);val f2=Fake();f2.products=listOf(StoreProduct(id=3),StoreProduct(id=2),StoreProduct(id=1));val c2=StoreNovedadesController(this,f2);c2.start();advanceUntilIdle();c2.selectSort(StoreNovedadesSort.RECENT);assertEquals(listOf(3,2,1),c2.state.value.paging.items.map{it.id})}
}